// TMP102 digital temperature sensor - Arduino Uno R3 (ATmega328P) driver
// Datasheet: TI SBOS397I (Aug 2007, rev June 2024)
// Wiring: V+ -> 3.3V, GND -> GND, SDA -> A4, SCL -> A5, ADD0 -> GND, ALERT -> D2
// SDA, SCL and ALERT are pulled up to 3.3V with 5k resistors (datasheet p.20/22).
// Do NOT pull them up to 5V: absolute maximum on SCL/SDA/ADD0 is 4V (p.4).
#include <Wire.h>

const uint8_t PIN_SDA   = A4;  // I2C data  (TMP102 pin 6)
const uint8_t PIN_SCL   = A5;  // I2C clock (TMP102 pin 1)
const uint8_t PIN_ALERT = 2;   // ALERT open-drain output (TMP102 pin 3), active low (POL=0)

const uint8_t TMP102_ADDR = 0x48; // 1001000b with ADD0 = GND (Table 6-4, p.11)

// Pointer register values (Table 6-7, p.16)
const uint8_t REG_TEMP   = 0x00; // Temperature (read only)
const uint8_t REG_CONFIG = 0x01; // Configuration (R/W)
const uint8_t REG_TLOW   = 0x02; // T_LOW limit (R/W)
const uint8_t REG_THIGH  = 0x03; // T_HIGH limit (R/W)

// Configuration register (Tables 6-10 / 6-11, p.17)
// Byte 1: OS=0 R1=1 R0=1 F1=0 F0=0 POL=0 TM=0 SD=0  -> 0x60
// Byte 2: CR1=1 CR0=0 AL=1 EM=0 0 0 0 0            -> 0xA0 (4 Hz, normal 12-bit mode)
const uint8_t CFG_MSB = 0x60;
const uint8_t CFG_LSB = 0xA0;

const float LSB_DEG_C = 0.0625f; // 1 LSB = 0.0625 C (p.8, Table 6-2 p.9)

// Write pointer + 16-bit register, MSB first (Figure 6-2, p.13)
bool writeReg16(uint8_t reg, uint8_t msb, uint8_t lsb) {
  Wire.beginTransmission(TMP102_ADDR);
  Wire.write(reg);
  Wire.write(msb);
  Wire.write(lsb);
  return Wire.endTransmission() == 0;
}

// Write pointer, then read 2 bytes MSB first (Figure 6-3, p.14)
bool readReg16(uint8_t reg, uint16_t &val) {
  Wire.beginTransmission(TMP102_ADDR);
  Wire.write(reg);
  if (Wire.endTransmission() != 0) return false;
  if (Wire.requestFrom(TMP102_ADDR, (uint8_t)2) != 2) return false;
  uint8_t msb = Wire.read();
  uint8_t lsb = Wire.read();
  val = ((uint16_t)msb << 8) | lsb;
  return true;
}

// Convert raw temperature register to degrees C.
// Normal mode (EM=0): 12 bits left-justified in bits 15..4, byte2 D0 = 0 (Tables 6-8/6-9, p.17).
// Extended mode (EM=1): 13 bits in bits 15..3, byte2 D0 = 1.
// Negative values are two's complement (p.8-10).
float rawToCelsius(uint16_t raw) {
  int16_t counts;
  if (raw & 0x0001) {                      // extended 13-bit format
    counts = (int16_t)(raw >> 3);
    if (counts & 0x1000) counts -= 8192;   // sign-extend 13 bits
  } else {                                 // normal 12-bit format
    counts = (int16_t)(raw >> 4);
    if (counts & 0x0800) counts -= 4096;   // sign-extend 12 bits
  }
  return counts * LSB_DEG_C;
}

void setup() {
  Serial.begin(9600);
  pinMode(PIN_ALERT, INPUT);               // external 5k pull-up to 3.3V, no internal pull-up

  Wire.begin();
  // The AVR Wire library enables the ATmega328P internal pull-ups on SDA/SCL, which pull
  // to 5V and exceed the TMP102 4V absolute maximum (p.4). Turn them off; rely on the
  // external 5k pull-ups to 3.3V (p.20).
  digitalWrite(PIN_SDA, LOW);
  digitalWrite(PIN_SCL, LOW);
  Wire.setClock(100000);                   // 100 kHz, within fast mode 1 kHz..400 kHz (p.6)

  delay(20);                               // first conversion ready ~10 ms after power-up (p.15)

  if (!writeReg16(REG_CONFIG, CFG_MSB, CFG_LSB)) {
    Serial.println(F("TMP102 not found - check wiring and address (0x48 with ADD0=GND)"));
  } else {
    Serial.println(F("TMP102 configured: continuous conversion, 4 Hz, comparator mode"));
  }

  // Optional: change ALERT thresholds. Power-up defaults are THIGH = 80 C, TLOW = 75 C (p.19).
  // Limit registers use the same format as the temperature register (temp / 0.0625, left-justified).
  // Example: THIGH = 30 C -> 480 = 0x1E0 -> 0x1E00 ; TLOW = 25 C -> 400 = 0x190 -> 0x1900
  // writeReg16(REG_THIGH, 0x1E, 0x00);
  // writeReg16(REG_TLOW,  0x19, 0x00);
}

void loop() {
  uint16_t raw;
  if (readReg16(REG_TEMP, raw)) {
    float tempC = rawToCelsius(raw);
    Serial.print(F("Temp: "));
    Serial.print(tempC, 4);
    Serial.print(F(" C  raw=0x"));
    Serial.print(raw, HEX);
    Serial.print(F("  ALERT="));
    Serial.println(digitalRead(PIN_ALERT) ? F("inactive") : F("ACTIVE"));
  } else {
    Serial.println(F("I2C read error"));
  }
  delay(250);                              // matches default 4 Hz conversion rate (Table 6-5, p.15)
}
